{
  "findings": [
    {
      "check_id": "CKV_AWS_19",
      "title": "S3 bucket encryption is not explicitly configured",
      "resource": "aws_s3_bucket.financials",
      "severity": "MEDIUM",
      "explanation": "The bucket stores financial data but does not explicitly enforce server-side encryption in Terraform, leaving the required encryption posture undeclared."
    },
    {
      "check_id": "CKV_AWS_21",
      "title": "S3 bucket versioning is disabled",
      "resource": "aws_s3_bucket.financials",
      "severity": "MEDIUM",
      "explanation": "Without versioning, financial objects cannot be recovered easily after accidental overwrites or deletions."
    },
    {
      "check_id": "CKV_AWS_53",
      "title": "Public ACLs are not blocked",
      "resource": "aws_s3_bucket.financials",
      "severity": "HIGH",
      "explanation": "Although the current ACL is private, no bucket-level control prevents a future public ACL from exposing financial data."
    },
    {
      "check_id": "CKV_AWS_54",
      "title": "Public bucket policies are not blocked",
      "resource": "aws_s3_bucket.financials",
      "severity": "HIGH",
      "explanation": "The bucket does not reject public bucket policies, so a later policy change could make its financial data publicly accessible."
    },
    {
      "check_id": "CKV_AWS_55",
      "title": "Public ACLs are not ignored",
      "resource": "aws_s3_bucket.financials",
      "severity": "HIGH",
      "explanation": "The bucket is not configured to ignore public ACLs, allowing future object or bucket ACL changes to create unintended exposure."
    },
    {
      "check_id": "CKV_AWS_56",
      "title": "Public bucket access is not restricted",
      "resource": "aws_s3_bucket.financials",
      "severity": "HIGH",
      "explanation": "The bucket lacks an explicit restriction against public access granted through bucket policies or access points."
    },
    {
      "check_id": "UNKNOWN",
      "title": "Destructive deletion is enabled",
      "resource": "aws_s3_bucket.financials",
      "severity": "HIGH",
      "explanation": "Setting force_destroy to true allows Terraform to permanently delete the bucket and all financial object versions during resource destruction."
    }
  ],
  "patched_code": "resource \"aws_s3_bucket\" \"financials\" {\n  bucket        = \"${local.resource_prefix.value}-financials\"\n  acl           = \"private\"\n  force_destroy = false\n\n  versioning {\n    enabled = true\n  }\n\n  server_side_encryption_configuration {\n    rule {\n      apply_server_side_encryption_by_default {\n        sse_algorithm = \"AES256\"\n      }\n    }\n  }\n\n  tags = merge({\n    Name        = \"${local.resource_prefix.value}-financials\"\n    Environment = local.resource_prefix.value\n    }, {\n  })\n}\n\nresource \"aws_s3_bucket_public_access_block\" \"financials\" {\n  bucket = aws_s3_bucket.financials.id\n\n  block_public_acls       = true\n  block_public_policy     = true\n  ignore_public_acls      = true\n  restrict_public_buckets = true\n}\n",
  "fix_summary": "Enabled explicit server-side encryption and versioning, disabled destructive forced deletion, and added all four S3 public-access-block controls."
}
